\begin{ExamChoiceQuestion}[id=p001-q3,points=5,show-points=false]
设 $\mathrm{e}<x_1<x_2$，且 \ExamStatementMarker{1}$x_2\ln x_2>x_1\ln x_1$，\ExamStatementMarker{2}$x_1\ln x_2<x_2\ln x_1$，\ExamStatementMarker{3}$x_2\ln x_2<x_1\ln x_1$，\ExamStatementMarker{4}$x_1\ln x_2>x_2\ln x_1$。则下列不等式成立的是\ExamSelection
\ExamChoices{$\ExamCircledNumber{2}\ExamCircledNumber{3}$}{$\ExamCircledNumber{1}\ExamCircledNumber{2}$}{$\ExamCircledNumber{1}\ExamCircledNumber{4}$}{$\ExamCircledNumber{3}\ExamCircledNumber{4}$}
\end{ExamChoiceQuestion}

